    subroutine triangle_feec_operator_tables(order, gradient, curl, divergence, status)
        !! gradient(ndof, nl0): Nedelec dofs of the P_k Lagrange gradients.
        !! curl(nld, ndof): curl of the Nedelec basis at the P_{k-1} nodes.
